// === Tab: mySketch ===
let dotCnt = 512;
let dot = new Array(dotCnt);

class Dot {
  x;
  y;
  vx;
  vy;

  constructor() {
    do {
      x = random(width);
      y = random(height);
    } while (get(int(x), int(y))==color(0));

    let rad=random(TWO_PI);
    vx=cos(rad);
    vy=sin(rad);
  }

  function update() {
    x+=vx;
    if (x<0 || x>width) {
      vx=-vx;
      x+=vx*2;
    }
    y+=vy;
    if (y<0 || y>width) {
      vy=-vy;
      y+=vy*2;
    }
    if (get(int(x), int(y))!=color(0)) {
      point(x, y);
      do {
        x = random(width);
        y = random(height);
      } while (get(int(x), int(y))==color(0));
      var rad=random(TWO_PI);
      vx=cos(rad);
      vy=sin(rad);
    }
  }
}

let ballCnt =4;
let ball = new Array(ballCnt);

class Ball {
  x;
  y;
  vx;
  vy;

  constructor() {
    x = width/2; 
    y = height/2;
    vx=0;
    vy=0;
  }

  function update() {
    vx += random(-1, 1);
    vy += random(-1, 1);
    if (abs(vx) > 10) vx=0;
    if (abs(vy) > 10) vy=0; 
    x+=vx;
    y+=vy;
    if (x<0 || x>width ) { 
      x -=vx ; 
      vx = -vx;
    }
    if (y<0 || y>height) { 
      y -=vy ; 
      vy = -vy;
    }
    point (x, y);
  }
}

function setup() {
  createCanvas(640, 640);
  background(0);
  strokeWeight(10);
  stroke(255);
  noFill();
  ellipse(width/2, height/2, height/2, height/2);

  stroke(255);
  for (i=0; i<dot.length; i++) {
    dot[i] = new Dot();
  }
  for (i=0; i < ball.length; i++) {
    ball[i] = new Ball();
  }
}

function draw() {
  stroke(0);
  strokeWeight(70);
  for (let b of ball) {
    b.update();
  }

  strokeWeight(9);
  stroke(255);
  for (let d of dot) {
    d.update();
  }
  fill(0);
  noStroke();
  ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 60, 60);
}

